UPDATE MGCMTBLDEF SET DATA_3_PRT='FMB BOARD ID', DATA_3_FMT='A', DATA_3_SIZE=10 WHERE FACTORY='SYSTEM' AND TABLE_NAME='SUB_AREA';

BEGIN
	FOR REC IN (
		SELECT DISTINCT FACTORY FROM MWIPFACDEF
		MINUS
		SELECT DISTINCT FACTORY FROM MGCMTBLDEF 
		WHERE TABLE_NAME = 'SUB_AREA' AND KEY_3_FMT <> ' '
		) 
	LOOP
    UPDATE MGCMTBLDEF SET DATA_3_PRT='FMB BOARD ID', DATA_3_FMT='A', DATA_3_SIZE=10 WHERE FACTORY=REC.FACTORY AND TABLE_NAME='SUB_AREA';
	END LOOP;
END ;
