DECLARE
    FNC_OLD         MSECFUNDEF%ROWTYPE;
    FNC_TMP         MSECFUNDEF%ROWTYPE;
    GFN_OLD         MSECGRPFUN%ROWTYPE;
    TMP_FUNC_NAME   VARCHAR2(20);
BEGIN
    FOR FNC IN (
