                            'RAS1022','RAS2001','RAS2002','RAS2003','RAS2004','RAS2005','RAS2006','RAS2007','RAS2008','RAS2009','RAS2010','RAS2011','RAS2013','RAS2014','RAS2015','RAS2016','RAS2017','RAS3001','RAS3002','RAS3004','RAS3005',
                            'RAS3006','RAS3007','RAS3008','RAS3009','RAS3010','RAS3011','RAS3012','RAS3013','RAS3014','RAS3015','RAS3016','RAS3017','RAS3018','RAS3019','RAS3020','RAS3021','RAS3022','RAS3023','RAS3024','RAS3025','RAS3026',
                            'RCP1001','RCP1002','RCP1003','RCP1004','RCP2001','RCP2002','RCP3001','RCP3002','RTD1001','RTD1002','RTD1003','RTD1004','RTD1005','RTD1007','RTD2001','RTD2002','RTD3001','RTD3002','RTD3003','RTD3004','SEC1001',
