        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          DBMS_OUTPUT.PUT_LINE ('NOT FOUND FUNCTION');
        END;

        FOR GFN IN (
            SELECT * FROM MSECGRPFUN
            WHERE FUNC_NAME = FNC.FUNC_NAME
