        LOOP

            SELECT * INTO GFN_OLD FROM MSECGRPFUN_OLD 
            WHERE FUNC_NAME = GFN.FUNC_NAME
              AND FACTORY = GFN.FACTORY
              AND PROGRAM_ID = GFN.PROGRAM_ID
              AND SEC_GRP_ID = GFN.SEC_GRP_ID;
            

            SELECT * INTO FNC_TMP FROM MSECFUNDEF WHERE FUNC_NAME = FNC.FUNC_NAME;

