                    SELECT FUNC_NAME INTO TMP_FUNC_NAME FROM MTMPWRNFUN WHERE FUNC_NAME = FNC_OLD.FUNC_NAME AND CTL_NAME = FNC_OLD.CTL_NAME_1;
