                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSE
                            INSERT INTO MSECFUNDEF_ERR VALUES(FNC_OLD.FUNC_NAME, FNC_OLD.CTL_NAME_1);
                        END IF;
                    END IF;
                END;
            END IF;

            SELECT * INTO FNC_TMP FROM MSECFUNDEF WHERE FUNC_NAME = FNC.FUNC_NAME;

            IF FNC_OLD.CTL_NAME_2 <> ' ' THEN
