                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSIF FNC_TMP.OPT_NAME_7 = ' ' THEN
                            UPDATE MSECFUNDEF SET OPT_NAME_7 = FNC_OLD.CTL_NAME_2
                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSIF FNC_TMP.OPT_NAME_6 = ' ' THEN
                            UPDATE MSECFUNDEF SET OPT_NAME_6 = FNC_OLD.CTL_NAME_2
                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSIF FNC_TMP.OPT_NAME_5 = ' ' THEN
                            UPDATE MSECFUNDEF SET OPT_NAME_5 = FNC_OLD.CTL_NAME_2
                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSIF FNC_TMP.OPT_NAME_4 = ' ' THEN
                            UPDATE MSECFUNDEF SET OPT_NAME_4 = FNC_OLD.CTL_NAME_2
                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSIF FNC_TMP.OPT_NAME_3 = ' ' THEN
                            UPDATE MSECFUNDEF SET OPT_NAME_3 = FNC_OLD.CTL_NAME_2
                            WHERE FUNC_NAME = FNC_OLD.FUNC_NAME;
                        ELSIF FNC_TMP.OPT_NAME_2 = ' ' THEN
